<?php
session_start();require_once '../shared/config.php';requireLogin('customer','login.php');$db=getDB();$customerId=(int)$_SESSION['customer_id'];$error='';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 if(!isset($_FILES['photo'])||$_FILES['photo']['error']!==UPLOAD_ERR_OK){$error='Please choose a photo.';}
 elseif($_FILES['photo']['size']>5*1024*1024){$error='Photo must be 5MB or smaller.';}
 else{
  $ext=strtolower(pathinfo($_FILES['photo']['name'],PATHINFO_EXTENSION));$allowed=['jpg','jpeg','png','webp'];
  if(!in_array($ext,$allowed,true))$error='Only JPG, PNG or WEBP photos are allowed.';
  else{
   $dir=__DIR__.'/../uploads/avatars';if(!is_dir($dir))mkdir($dir,0755,true);
   $name='customer_'.$customerId.'_'.bin2hex(random_bytes(8)).'.'.$ext;
   if(move_uploaded_file($_FILES['photo']['tmp_name'],$dir.'/'.$name)){
    $height=(float)($_POST['height']??0);$measurements=[];foreach(['chest','waist','hip','shoulder','sleeve'] as $k){$v=(float)($_POST[$k]??0);if($v>0)$measurements[$k]=$v;}
    $prefs=['style'=>trim($_POST['style']??''),'notes'=>trim($_POST['notes']??'')];
    $st=$db->prepare("INSERT INTO user_avatars(customer_id,photo_path,height,measurements,preferences) VALUES(?,?,?,?,?)");$st->execute([$customerId,$name,$height?:null,json_encode($measurements),json_encode($prefs)]);
    $message='Avatar photo profile saved.';
   }else $error='Could not save the photo.';
  }
 }
}
$st=$db->prepare("SELECT * FROM user_avatars WHERE customer_id=? ORDER BY created_at DESC");$st->execute([$customerId]);$avatars=$st->fetchAll();
?><!doctype html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Avatar Profile – O2O Tradition</title><style>
body{font-family:Arial;background:#FAF6EE;color:#3D2B0F;margin:0}.nav{background:#1A1108;color:#C9A84C;padding:18px 28px;display:flex;justify-content:space-between}.nav a{color:#E8CC82;margin-left:15px;text-decoration:none}.main{max-width:850px;margin:auto;padding:30px}.hero,.card{background:#fff;padding:24px;margin-bottom:18px;border:1px solid #E8E0D0}.hero{background:#28170c;color:#fff}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.label{display:block;font-size:11px;font-weight:bold;margin:8px 0}.input{width:100%;padding:11px;box-sizing:border-box}.btn{margin-top:18px;padding:12px 20px;background:#1A1108;color:#C9A84C;border:0}.msg{background:#ECFDF5;color:#065F46;padding:12px}.err{background:#FEF2F2;color:#991B1B;padding:12px}.avatar{padding:14px;border:1px solid #eee;margin-top:10px}.small{font-size:12px;color:#777;line-height:1.6}@media(max-width:650px){.grid{grid-template-columns:1fr}}</style></head><body><div class="nav"><b>O2O Tradition</b><div><a href="home.php">Home</a><a href="size_profile.php">Size Profile</a></div></div><main class="main"><section class="hero"><h1>👤 AI Avatar Profile</h1><p>Upload a clear photo and optional measurements. This creates the customer-side avatar foundation for future virtual styling and try-on.</p></section><?php if($message):?><div class="msg"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="err"><?=htmlspecialchars($error)?></div><?php endif;?><section class="card"><h2>Create Avatar Profile</h2><form method="POST" enctype="multipart/form-data"><label class="label">Photo (JPG, PNG or WEBP, max 5MB)</label><input class="input" type="file" name="photo" accept=".jpg,.jpeg,.png,.webp" required><div class="grid"><?php foreach(['height'=>'Height','chest'=>'Chest','waist'=>'Waist','hip'=>'Hip','shoulder'=>'Shoulder','sleeve'=>'Sleeve'] as $k=>$l):?><div><label class="label"><?=$l?> (cm, optional)</label><input class="input" type="number" step="0.1" min="0" name="<?=$k?>"></div><?php endforeach;?></div><label class="label">Preferred style (optional)</label><input class="input" name="style" placeholder="e.g. classic, festive, minimal"><label class="label">Notes (optional)</label><textarea class="input" name="notes" rows="3"></textarea><button class="btn">Save Avatar Profile</button></form></section><section class="card"><h2>Your saved avatar profiles</h2><?php if(!$avatars):?><p class="small">No avatar profiles yet.</p><?php else:foreach($avatars as $a):?><div class="avatar"><b>Avatar created <?=date('d M Y',strtotime($a['created_at']))?></b><p class="small">Photo stored securely as an account asset. Height: <?=htmlspecialchars($a['height']??'—')?> cm.</p></div><?php endforeach;endif;?></section><section class="card"><b>Privacy & accuracy:</b><p class="small">Your photo is used as an account asset for future AI styling features. A photo-based avatar or try-on result should be treated as an approximation, not a guarantee of appearance or fit.</p></section></main></body></html>